    }
  },
  {
    json: {
      adArchiveID: "1048291043748295",
      pageName: "MySivi - AI English Speaking Tutor",
      caption: "Limited Time Offer! 🚀 Get 50% OFF on MySivi Annual Fluency Pass. Unlock unlimited voice conversations, daily speaking drills, vocabulary challenges, and personalized accent feedback. Offer ends this Sunday midnight!",
      ctaText: "Get Offer",
      linkUrl: "https://mysivi.ai/promo50",
      impressions: "180,000 - 240,000",
      activeDays: 12,
      mediaType: "image"
    }
  }
];

// AI Creative Intelligence Analysis (Extract Hook, Body, CTA & Score)
const items = $input.all();
const analyzed = [];

for (const item of items) {
  const ad = item.json;
  const caption = ad.caption || "";

  let hook = "";
  let hookType = "Pain Point";
  let body = "";
  let cta = ad.ctaText || "Learn More";
  let score = 7.0;
  let audience = "Indian English Learners";
  let strengths = [];
  let weaknesses = [];
  let recommendation = "";

  if (ad.adArchiveID === "1048291043748291") {
    hook = "Stuck while speaking English in office meetings? 🤐";
    hookType = "Relatable Pain Point / Problem Agitation";
    body = "Focuses on professional freezing during meetings; offers 1-on-1 private AI voice practice without judgment; 15 mins a day micro-habit; 250k+ Indian users social proof.";
    score = 9.4;
    audience = "Corporate / IT Working Professionals (Bangalore/Hyderabad/Pune)";
    strengths = ["Eliminates primary barrier: fear of social judgment", "High-income target demographic with ability to pay", "Low friction: 15 mins daily commitment"];
    weaknesses = ["Could feature audio sample previews of AI tutor"];
    recommendation = "Test niche hooks for client standups vs manager appraisals.";
  } else if (ad.adArchiveID === "1048291043748292") {
    hook = "Cracking job interviews requires more than technical skills. You need fluent English!";
    hookType = "Career Ambition & Salary Aspiration";
    body = "Stops silent mental translation; offers interactive mock AI interviews for tech & HR rounds; promises 2x salary jump.";
    score = 8.8;
    audience = "Job Seekers & Fresh Graduates preparing for placements";
    strengths = ["Direct ROI linked to career salary boost", "Interactive AI mock interview feature showcase"];
    weaknesses = ["Slightly generic interview claim"];
    recommendation = "Add specific salary benchmark proof points (e.g. 4 LPA to 8 LPA).";
  } else if (ad.adArchiveID === "1048291043748293") {
    hook = "English coaching classes take 3 months and cost ₹15,000+.";
    hookType = "Price / Value Anchoring";
    body = "Contrasts high cost and travel of offline coaching vs ₹499/mo 24/7 personal smartphone AI tutor.";
    score = 8.5;
    audience = "Tier 2 & 3 College Students & Value Shoppers";
    strengths = ["Strong price anchoring against expensive offline alternatives", "24/7 accessibility"];
    weaknesses = ["Relies heavily on price discounting"];
    recommendation = "Pair with instant free CEFR speaking level assessment.";
  } else if (ad.adArchiveID === "1048291043748294") {
    hook = "\"Maine socha tha English seekhna bohot tough hai... par MySivi ne 21 dino me meri hesitation khatam kar di!\"";
    hookType = "Hinglish UGC Social Proof";
    body = "Relatable story of Priya (Pune engineer) overcoming hesitation in client meetings.";
    score = 9.1;
    audience = "Tier 2 native speakers who understand English but hesitate to speak";
    strengths = ["Authentic conversational tone", "Proven UGC format for high Meta CTR"];
    weaknesses = ["CTA 'Learn More' is weaker than 'Install Now'"];
    recommendation = "Change CTA button from Learn More to Install Now to improve conversion rate.";
  } else {
    hook = "Limited Time Offer! 🚀 Get 50% OFF on MySivi Annual Fluency Pass.";
    hookType = "Direct Promotional Discount";
    body = "Urgency-driven promotion on annual access to drills and accent feedback.";
    score = 7.2;
    audience = "Warm retargeting audience who already installed the app";
    strengths = ["High urgency countdown"];
    weaknesses = ["Weak hook for cold top-of-funnel traffic; no emotional resonance"];
    recommendation = "Reserve this creative strictly for warm bottom-of-funnel retargeting.";
  }

  analyzed.push({
    adArchiveID: ad.adArchiveID,
    hook: hook,
    hook_type: hookType,
    body: body,
    cta: cta,
    target_audience: audience,
    performance_score: score,
    impressions: ad.impressions,
    activeDays: ad.activeDays,
    strengths: strengths,
    weaknesses: weaknesses,
    improvement_recommendation: recommendation
  });
}

return analyzed.map(d => ({ json: d }));

// Creative Winner Ranker
const items = $input.all().map(item => item.json);

// Sort descending by performance score
items.sort((a, b) => (b.performance_score || 0) - (a.performance_score || 0));
const bestAd = items[0] || {};

return [
  {
    json: {
      analyzedAt: new Date().toISOString(),
      totalAdsAnalyzed: items.length,
      winningAd: {
        adArchiveID: bestAd.adArchiveID,
        hook: bestAd.hook,
        body: bestAd.body,
        cta: bestAd.cta,
        performanceScore: bestAd.performance_score,
        impressions: bestAd.impressions,
        activeDays: bestAd.activeDays
      },
      winningReason: `Ad ${bestAd.adArchiveID} ('${bestAd.hook}') scored highest (${bestAd.performanceScore}/10). It directly targets workplace meeting anxiety, removes peer judgment fear, and shows the longest run longevity in Meta Ad Library.`,
      allRankedCreatives: items
    }
  }
];
